-- ============================================================================
-- One-time historical import — Monitoring Project Topografi Pertamina EP
-- Zona 4, cleaned from the source workbook (UMK, PPBJ Barang, PPBJ Jasa,
-- Gaji PTT Project, SPPD, MCU tabs) as of 2026-08-30.
--
-- NOT idempotent like seed.sql — this is real historical data, not reference
-- data, so it only inserts once. Re-running supabase db reset (which re-runs
-- every file in supabase/seed/) must not duplicate these 986 rows.
--
-- Run after seed.sql (chart_of_accounts must exist first for the kode_akun
-- foreign key). Local dev: supabase db reset picks up every file in
-- supabase/seed/ automatically. Cloud: psql "$SUPABASE_DB_URL" -f supabase/seed/finance_transactions_import.sql
-- ============================================================================

do $$
begin
  if exists (select 1 from finance_transactions limit 1) then
    raise notice 'finance_transactions already has data — skipping historical import.';
    return;
  end if;


end $$;
